  "inlineSchema": "// Patient Tracking & Reporting System — Prisma schema\n// Modeled on the DSD AHF Contribution Monthly Report + Clinicians' Index\n// Testing Referral List forms.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum ReportStatus {\n  DRAFT\n  SUBMITTED\n  VERIFIED\n}\n\nenum WeeklyReportStatus {\n  DRAFT\n  SUBMITTED\n}\n\nenum UserRole {\n  CAPTURER\n  VERIFIER\n  PROGRAM_MANAGER\n  ADMIN\n  VIEWER // read-only, system-wide oversight — a former ADMIN lands here\n  // after appointing a successor; never directly assignable via\n  // the normal \"Add user\" flow, only via the appoint-admin handoff\n}\n\nenum UnitType {\n  COUNT\n  PERCENT\n  RATE_PER_DAY\n  RATE_PER_WEEK\n}\n\nmodel Facility {\n  id           String   @id @default(uuid())\n  name         String\n  facilityCode String   @unique\n  district     String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  users            User[]\n  monthlyReports   MonthlyReport[]\n  weeklyReports    WeeklyReport[]\n  indexTestingLogs IndexTestingReferral[]\n\n  @@map(\"facilities\")\n}\n\nmodel PerformanceCycle {\n  id        String   @id @default(uuid())\n  label     String   @unique // e.g. \"2025/2026\"\n  startDate DateTime\n  endDate   DateTime\n\n  monthlyReports   MonthlyReport[]\n  weeklyReports    WeeklyReport[]\n  indicatorTargets IndicatorTarget[]\n\n  @@map(\"performance_cycles\")\n}\n\nmodel Indicator {\n  id        String   @id @default(uuid())\n  code      String   @unique // e.g. \"PREP_STARTED\"\n  label     String // e.g. \"# of clients started on PrEP\"\n  unitType  UnitType @default(COUNT)\n  sortOrder Int      @default(0)\n\n  monthlyEntries   MonthlyReportEntry[]\n  weeklyEntries    WeeklyReportEntry[]\n  indicatorTargets IndicatorTarget[]\n\n  @@map(\"indicators\")\n}\n\nmodel IndicatorTarget {\n  id          String @id @default(uuid())\n  indicatorId String\n  cycleId     String\n  targetValue String // free text to allow \"1 per day\", \"100% eligible\", \"10 per week\"\n\n  indicator Indicator        @relation(fields: [indicatorId], references: [id])\n  cycle     PerformanceCycle @relation(fields: [cycleId], references: [id])\n\n  @@unique([indicatorId, cycleId])\n  @@map(\"indicator_targets\")\n}\n\nmodel User {\n  id           String   @id @default(uuid())\n  name         String\n  email        String   @unique\n  passwordHash String\n  role         UserRole @default(CAPTURER)\n  facilityId   String?\n  createdAt    DateTime @default(now())\n\n  facility              Facility?       @relation(fields: [facilityId], references: [id])\n  capturedReports       MonthlyReport[] @relation(\"CapturedBy\")\n  capturedWeeklyReports WeeklyReport[]  @relation(\"WeeklyCapturedBy\")\n\n  @@map(\"users\")\n}\n\nmodel MonthlyReport {\n  id           String       @id @default(uuid())\n  facilityId   String\n  cycleId      String\n  month        String // \"Oct\" .. \"Sep\" matching the performance-cycle year\n  status       ReportStatus @default(DRAFT)\n  capturedById String?\n  verifiedBy   String?\n  verifiedDate DateTime?\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  facility   Facility             @relation(fields: [facilityId], references: [id])\n  cycle      PerformanceCycle     @relation(fields: [cycleId], references: [id])\n  capturedBy User?                @relation(\"CapturedBy\", fields: [capturedById], references: [id])\n  entries    MonthlyReportEntry[]\n\n  @@unique([facilityId, cycleId, month])\n  @@map(\"monthly_reports\")\n}\n\nmodel MonthlyReportEntry {\n  id          String  @id @default(uuid())\n  reportId    String\n  indicatorId String\n  value       Decimal @db.Decimal(10, 2)\n\n  report    MonthlyReport @relation(fields: [reportId], references: [id], onDelete: Cascade)\n  indicator Indicator     @relation(fields: [indicatorId], references: [id])\n\n  @@unique([reportId, indicatorId])\n  @@map(\"monthly_report_entries\")\n}\n\n// One WeeklyReport per facility/cycle/month/week. Every save automatically\n// syncs into the MonthlyReport's running totals — see\n// WeeklyReportsService.upsert for the delta logic: it compares this save's\n// values against what the week previously held and adjusts the monthly\n// entries by the *difference*, so editing a week (not just creating one)\n// keeps the monthly total correct instead of double-counting.\nmodel WeeklyReport {\n  id           String             @id @default(uuid())\n  facilityId   String\n  cycleId      String\n  month        String // the month this week rolls up into, e.g. \"Jul\"\n  weekLabel    String // e.g. \"Week 1\", \"06-12 Jul\"\n  status       WeeklyReportStatus @default(DRAFT)\n  capturedById String?\n  lastSyncedAt DateTime? // set every time this week's values are synced into the monthly report\n  createdAt    DateTime           @default(now())\n  updatedAt    DateTime           @updatedAt\n\n  facility   Facility            @relation(fields: [facilityId], references: [id])\n  cycle      PerformanceCycle    @relation(fields: [cycleId], references: [id])\n  capturedBy User?               @relation(\"WeeklyCapturedBy\", fields: [capturedById], references: [id])\n  entries    WeeklyReportEntry[]\n\n  @@unique([facilityId, cycleId, month, weekLabel])\n  @@map(\"weekly_reports\")\n}\n\nmodel WeeklyReportEntry {\n  id          String  @id @default(uuid())\n  reportId    String\n  indicatorId String\n  // Defaults to 0 — every indicator gets a row for every week even if the\n  // capturer left the field blank, so an untouched line is an explicit\n  // zero, not a missing value that would silently skip the monthly total.\n  value       Decimal @default(0) @db.Decimal(10, 2)\n\n  report    WeeklyReport @relation(fields: [reportId], references: [id], onDelete: Cascade)\n  indicator Indicator    @relation(fields: [indicatorId], references: [id])\n\n  @@unique([reportId, indicatorId])\n  @@map(\"weekly_report_entries\")\n}\n\nmodel IndexTestingReferral {\n  id          String   @id @default(uuid())\n  facilityId  String\n  date        DateTime\n  fileNo      String\n  riskReasons String[] // e.g. [\"UNSUPPRESSED_VL\", \"NEW_STI\", \"RE_ENGAGEMENT\"]\n  otherRisk   String?\n  receivedBy  String // counsellor name\n  completedBy String?\n  createdAt   DateTime @default(now())\n\n  facility Facility @relation(fields: [facilityId], references: [id])\n\n  @@map(\"index_testing_referrals\")\n}\n",
  "inlineSchemaHash": "fb91c6f22e2275e405b757cb336d68d9d0b66ef2e06c4d97850437c07f9faf87",
